#include <termin/render/render_scene_item_collector.hpp>
#include <tgfx/resources/tc_material_registry.h>
#include <dlfcn.h>
#include <cstdio>
static bool heavy = true;
extern "C" void set_dependency_control_heavy(bool value) { heavy = value; }
namespace termin {
bool collect_scene_materials(const RenderSceneItemCollectRequest& request, tc_material_sink& sink) {
    if (!heavy) {
        using Callback = bool (*)(const RenderSceneItemCollectRequest&, tc_material_sink&);
        static Callback lightweight = reinterpret_cast<Callback>(dlsym(RTLD_NEXT,
            "_ZN6termin23collect_scene_materialsERKNS_29RenderSceneItemCollectRequestER16tc_material_sink"));
        if (!lightweight) { std::fprintf(stderr, "benchmark lightweight symbol: %s\n", dlerror()); return false; }
        return lightweight(request, sink);
    }
    static RenderSceneItemCollector collector;
    if (!collector.collect(request)) return false;
    for (const auto& item : collector.items()) {
        tc_material_handle handle = item.material;
        if (!tc_material_get(handle) && item.material_phase) handle = item.material_phase->owner_material;
        if (tc_material_get(handle) && !sink.emit(handle, sink.user_data)) return false;
    }
    return true;
}
}
